Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline constants, ideal for simple value combinations ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00, DisplayName = "10% off $100")]
    [DataRow(50.00, 0.25, 37.50, DisplayName = "25% off $50")]
    [DataRow(200.00, 0.00, 200.00, DisplayName = "No discount")]
    [DataRow(80.00, 1.00, 0.00, DisplayName = "100% discount")]
    public void ApplyDiscount_ReturnsExpected(double price, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: use when you need decimals, complex objects, or computed data ---

    public static IEnumerable<object[]> BulkDiscountCases =>
    [
        [1000m, 0.15m, 850.00m],
        [49.99m, 0.50m, 24.995m],
        [0m, 0.10m, 0m],
    ];

    [TestMethod]
    [DynamicData(nameof(BulkDiscountCases))]
    public void ApplyDiscount_BulkCases_ReturnsExpected(decimal price, decimal discount, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discount);
        Assert.AreEqual(expected, result);
    }

    // DynamicData with a method (useful for generated/computed test data)
    public static IEnumerable<object[]> GetEdgeCases()
    {
        yield return [int.MaxValue, 0.01m, (decimal)int.MaxValue * 0.01m];
        yield return [1, decimal.MaxValue, decimal.MaxValue];
    }

    [TestMethod]
    [DynamicData(nameof(GetEdgeCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_EdgeCases_ReturnsExpected(int quantity, decimal unitPrice, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, unitPrice);
        Assert.AreEqual(expected, result);
    }

    // --- Negative tests ---

    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(5, -3.00)]
    public void CalculateTotal_InvalidInput_Throws(int quantity, double unitPrice)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(quantity, (decimal)unitPrice));
    }

    [TestMethod]
    [DataRow(100.00, -0.01)]
    [DataRow(100.00, 1.01)]
    public void ApplyDiscount_InvalidDiscount_Throws(double price, double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discount));
    }
}
```

**Key best practices shown:**

| Practice | Why |
|----------|-----|
| `DataRow` for simple primitives | Inline, readable, no extra method needed |
| `DynamicData` for decimals/complex types | `DataRow` only supports compile-time constants |
| `DisplayName` on DataRow | Gives meaningful test names in explorer |
| Separate negative-case tests | Keeps happy-path and error-path distinct |
| `[TestInitialize]` for setup | Avoids repeated construction |
| Property vs Method source | Property for static data, Method for computed/generated |

**Note:** `DataRow` doesn't support `decimal` literals directly (they aren't compile-time constants in attributes), so use `double` and cast, or switch to `DynamicData` for exact decimal precision.
